def zone_axis_count(drawing: dict, zone: str) -> int:
    """某分区的轴线总数(竖向 + 横向)。"""
    z = drawing["zones"][zone]
    return len(z["vertical_labels"]) + len(z["horizontal_labels"])


def total_axis_count(drawing: dict, complete_only: bool = True) -> int:
    """全图轴线总数。complete_only 时跳过标注不完整的分区,避免分母偏小。"""
    return sum(
        zone_axis_count(drawing, z)
        for z, v in drawing["zones"].items()
        if not (complete_only and v.get("partial"))
    )


