def spacing_consistency(drawing: dict, zone: str) -> bool:
    """轴距条数应等于其覆盖的轴线数 - 1 —— 自检人工计数有没有漏。

    尺寸链未必贯通整个分区(如分区 2 底部只标到 2-12),故允许用
    `vertical_spacing_covers` 声明覆盖了前几根轴线。
    """
    z = drawing["zones"][zone]
    spacings = z.get("vertical_spacings_mm")
    if not spacings:
        return True
    covers = z.get("vertical_spacing_covers", len(z["vertical_labels"]))
    return len(spacings) == covers - 1


def horizontal_spacing_consistency(drawing: dict, zone: str) -> bool:
    """字母向轴距条数应等于字母轴线数 - 1。"""
    z = drawing["zones"][zone]
    spacings = z.get("horizontal_spacings_mm")
    if not spacings:
        return True
    return len(spacings) == len(z["horizontal_labels"]) - 1


def label_circle_budget(drawing: dict) -> int:
    """圈数 − 主轴线**圈数** = 附加轴线数。

    ⚠️ **不能写成「圈数 − 主轴线数」**:那假设每条轴线只有一个圈,而 §8.0.2
    允许轴线两端各注一个(实测分区 1 就有一条如此)。按旧写法算出 9,
    用字形判据直接数是 8——差的正是那条两端各一圈的轴线。
    """
    return (drawing["label_circles"]["count"]
            - drawing["main_label_circle_count"])
